defmodule Sinetex.Fixtures do
  @moduledoc false

  # Test-only PKI generated by test/support/gen_fixtures.sh.

  @dir Path.expand("../fixtures/generated", __DIR__)

  def dir, do: @dir

  def path(name), do: Path.join(@dir, name)

  def read!(name), do: File.read!(path(name))

  def ensure_generated! do
    unless File.exists?(path(".complete")) do
      script = Path.expand("gen_fixtures.sh", __DIR__)
      {output, status} = System.cmd("bash", [script, @dir], stderr_to_stdout: true)
      if status != 0, do: raise("gen_fixtures.sh failed:\n#{output}")
    end
  end

  # Loaded once per test run and cached.
  def identity(name, opts \\ []) do
    cached({:identity, name, opts}, fn ->
      {:ok, identity} = Sinetex.Identity.load(read!("#{name}.crt"), read!("#{name}.key"), opts)
      identity
    end)
  end

  def certificate(name, opts \\ []) do
    cached({:certificate, name, opts}, fn ->
      {:ok, cert} = Sinetex.Certificate.load(read!("#{name}.crt"), opts)
      cert
    end)
  end

  defp cached(key, fun) do
    key = {__MODULE__, key}

    case :persistent_term.get(key, nil) do
      nil ->
        value = fun.()
        :persistent_term.put(key, value)
        value

      value ->
        value
    end
  end

  # Deterministic generator (SHA-256 in counter mode) for known-answer tests.
  # Sinetex.Random only looks at it when compiled for the test environment.
  def install_rng(seed) do
    Process.put(:sinetex_test_rng_state, {seed, 0})

    Process.put(:sinetex_test_rng, fn n ->
      {seed, counter} = Process.get(:sinetex_test_rng_state)
      blocks = div(n + 31, 32)

      bytes =
        for i <- counter..(counter + blocks - 1)//1,
            into: <<>>,
            do: :crypto.hash(:sha256, seed <> <<i::32>>)

      Process.put(:sinetex_test_rng_state, {seed, counter + blocks})
      binary_part(bytes, 0, n)
    end)
  end

  def uninstall_rng do
    Process.delete(:sinetex_test_rng)
    Process.delete(:sinetex_test_rng_state)
  end

  # Re-encodes an envelope after changing its header.
  def tamper_header(envelope, fun) do
    {:ok, header, body} = Sinetex.Header.decode(envelope)
    Sinetex.Header.encode(fun.(header)) <> body
  end

  def flip_byte(bin, pos) do
    rest = binary_part(bin, pos + 1, byte_size(bin) - pos - 1)
    binary_part(bin, 0, pos) <> <<Bitwise.bxor(:binary.at(bin, pos), 0x01)>> <> rest
  end
end
